// GENERATED from docs/legal/privacy-policy.md by scripts/build-legal-pages.mjs. Do not edit.
// Served at /privacy; identical to app/public/privacy.html.
export const privacyPolicyHtml = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<meta name=\"description\" content=\"WanderBunnies Privacy Notice, version 3.0\">\n<title>Privacy Notice - WanderBunnies</title>\n<!-- GENERATED from docs/legal/privacy-policy.md by scripts/build-legal-pages.mjs. Do not edit. -->\n<style>\n  :root { color-scheme: light dark; --text: #263238; --heading: #111827; --muted: #5b6875; --border: #dbe3ec; --head-bg: #eef4fb; --bg: #ffffff; --link: #1d4ed8; --note-bg: #fff7ed; --note-border: #f97316; }\n  @media (prefers-color-scheme: dark) { :root { --text: #e2e8f0; --heading: #f8fafc; --muted: #94a3b8; --border: #334155; --head-bg: #1e293b; --bg: #0f172a; --link: #93c5fd; --note-bg: #3b2410; --note-border: #fb923c; } }\n  body { font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, Helvetica, Arial, sans-serif; line-height: 1.65; color: var(--text); background: var(--bg); max-width: 900px; margin: 0 auto; padding: 32px 16px; }\n  h1 { color: var(--heading); border-bottom: 2px solid var(--border); padding-bottom: 10px; }\n  h2 { color: var(--heading); margin-top: 34px; }\n  h3 { color: var(--heading); margin-top: 24px; }\n  p, li { max-width: 80ch; }\n  table { width: 100%; border-collapse: collapse; margin: 18px 0 24px; display: block; overflow-x: auto; }\n  th, td { border: 1px solid var(--border); padding: 10px; text-align: left; vertical-align: top; }\n  th { background: var(--head-bg); }\n  blockquote { background: var(--note-bg); border-left: 5px solid var(--note-border); margin: 18px 0; padding: 10px 16px; }\n  a { color: var(--link); }\n  .footer { margin-top: 48px; padding-top: 18px; border-top: 1px solid var(--border); color: var(--muted); font-size: .92em; }\n</style>\n</head>\n<body>\n<h1>Privacy Notice</h1>\n<p><strong>WanderBunnies</strong> — Version 3.0, effective October 8, 2026.</p>\n<blockquote>\n<p><strong>What changed in this version:</strong> operator and contact details are updated; accounts require age 16 or older everywhere; optional product analytics and optional detailed diagnostics are described (both are <strong>off unless you turn them on</strong>); we added push notification tokens, cost metering, a retention schedule, and a way to delete your analytics data yourself.</p>\n</blockquote>\n<p>This Privacy Notice explains how <strong>Tristan Duerk</strong>, an individual trading as WanderBunnies (&quot;WanderBunnies,&quot; &quot;we,&quot; &quot;us,&quot; or &quot;our&quot;), processes personal data when you use our web, mobile, and related services (the &quot;Service&quot;).</p>\n<h2>1. Controller and contact details</h2>\n<p>The data controller is:</p>\n<ul>\n<li><strong>Legal name:</strong> Tristan Duerk</li>\n<li><strong>Trading name:</strong> WanderBunnies</li>\n<li><strong>Registered/business address:</strong> 4 Dickinson Circle, Shrewsbury, MA 01545, USA</li>\n<li><strong>Privacy contact:</strong> <a href=\"mailto:support@wander-bunnies.com\">support@wander-bunnies.com</a></li>\n<li><strong>EU and UK representative:</strong> none appointed at this time.</li>\n<li><strong>Data Protection Officer:</strong> none designated.</li>\n</ul>\n<p>For privacy requests, please identify yourself, describe the request, and provide the email address associated with your account. We may request reasonable information to verify your identity.</p>\n<h2>2. Personal data we collect</h2>\n<table>\n<thead>\n<tr>\n<th>Category</th>\n<th>Examples</th>\n<th>How collected</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Account and authentication</td>\n<td>Name, email address, username, password credentials, sign-in provider, account role, email-verification status, date of birth or an age confirmation, authentication and session identifiers.</td>\n<td>Registration, login, Google, Apple or other enabled sign-in providers, and account management.</td>\n</tr>\n<tr>\n<td>Profile and preference data</td>\n<td>First and last name, home address, preferred airport, optional age and gender, travel preferences (such as pace, comfort level and interests), temperature, appearance and map preferences, family or fellow-traveler relationships, and related contact details.</td>\n<td>Information you enter or authorize another group member to share. All optional profile fields are optional.</td>\n</tr>\n<tr>\n<td>Trip and collaboration data</td>\n<td>Destinations, dates, flights, lodging, activities, transportation, itineraries, notes, packing lists, expenses, payments recorded in a shared ledger, comments, chat, reactions, presence, invitations, and follow codes.</td>\n<td>Information you create, upload, receive through collaboration, or import.</td>\n</tr>\n<tr>\n<td>Imported and uploaded content</td>\n<td>Documents, PDFs, images and videos you choose to upload or share into the app, emails, email headers and bodies, attachments, extracted travel details, filenames, source metadata, and review history.</td>\n<td>Manual uploads, the photo picker, sharing from another app, forwarded email, and optional Gmail import. We only access photos or videos you select or share; we do not use your camera or browse your photo library.</td>\n</tr>\n<tr>\n<td>Gmail and Google data</td>\n<td>Read-only inbox messages and attachments within the authorized scope, the connected Google account address, OAuth tokens, token status, and import history.</td>\n<td>Only after you authorize Gmail access and while the connection remains enabled.</td>\n</tr>\n<tr>\n<td>Billing and transaction data</td>\n<td>Stripe customer, subscription, invoice, tax, payment status, plan, entitlement, and webhook identifiers. Payment-card details are handled by Stripe rather than stored by WanderBunnies.</td>\n<td>Subscription checkout, billing management, and payment events.</td>\n</tr>\n<tr>\n<td>Necessary technical and security data</td>\n<td>IP address, user-agent, device or app information, timestamps, request and error logs, security events, and server-side error reports.</td>\n<td>Use of the Service. Needed to run, secure and fix the Service; not optional.</td>\n</tr>\n<tr>\n<td>Push notification tokens</td>\n<td>A device push token (encrypted before storage) and notification preferences.</td>\n<td>When you allow notifications on a mobile device. Removed when you sign out of that device or delete your account.</td>\n</tr>\n<tr>\n<td>Service usage and cost metering</td>\n<td>Which features used paid services (such as AI providers or maps), the units used, and the estimated cost, linked to your account and trip.</td>\n<td>Automatically when you use those features. Used to enforce plan limits and manage our costs; linkage to you is removed after 13 months.</td>\n</tr>\n<tr>\n<td>Optional product analytics (only if you turn it on)</td>\n<td>Which features you view and use, task outcomes, session timing, platform, app version and browser family, and whether activity happened before, during or after a trip&#39;s scheduled dates. Linked to a random pseudonym for your account.</td>\n<td>Only after you opt in under <strong>Account → Privacy</strong>. Never your location, messages, trip text, or imported content.</td>\n</tr>\n<tr>\n<td>Optional detailed diagnostics (only if you turn it on)</td>\n<td>App crash reports, performance timings (such as how long trips and pages take to load) and session health, linked to a random pseudonym for your account.</td>\n<td>Only after you opt in under <strong>Account → Privacy</strong>. Sent to Sentry.</td>\n</tr>\n<tr>\n<td>Affiliate and external-link data</td>\n<td>Selected activity or destination parameters, an affiliate redirect token, referral/click information, and technical data received when an external link is opened.</td>\n<td>When an eligible GetYourGuide or other partner link is requested or opened.</td>\n</tr>\n</tbody></table>\n<p>Do not upload passports, government identification, payment-card numbers, health information, or other sensitive information unless the feature specifically requires it and you have authority to do so. Travel documents may incidentally contain sensitive personal data belonging to you or other people.</p>\n<h2>3. How we use personal data and our legal bases</h2>\n<table>\n<thead>\n<tr>\n<th>Purpose</th>\n<th>Legal basis used where GDPR applies</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Create and secure accounts, authenticate users, confirm the minimum age, provide itineraries, collaboration, import, chat, notifications, support, and requested features.</td>\n<td>Performance of a contract; steps at your request before entering a contract.</td>\n</tr>\n<tr>\n<td>Process Gmail connections, imports, uploads, extraction, and review workflows.</td>\n<td>Performance of a contract; consent where applicable to an optional connected-account or import feature.</td>\n</tr>\n<tr>\n<td>Process subscriptions, taxes, invoices, refunds, fraud checks, and payment disputes; keep billing records.</td>\n<td>Performance of a contract and compliance with legal obligations.</td>\n</tr>\n<tr>\n<td>Enforce plan limits and quotas, and meter the cost of paid services per account and trip.</td>\n<td>Performance of a contract (plan limits) and legitimate interests (managing service costs).</td>\n</tr>\n<tr>\n<td>Operate, maintain, secure, debug, prevent abuse, and keep server-side error reports and security logs.</td>\n<td>Legitimate interests, balanced against your rights and expectations; legal obligation where applicable.</td>\n</tr>\n<tr>\n<td>Send service, security, billing, and account notices.</td>\n<td>Performance of a contract or legitimate interests. Marketing messages require consent where required.</td>\n</tr>\n<tr>\n<td>Generate AI-assisted itineraries, extraction results, summaries, and recommendations.</td>\n<td>Performance of a contract or your request for the feature; consent where a separate optional processing activity requires it.</td>\n</tr>\n<tr>\n<td>Optional product analytics: understand which features are valuable and improve them.</td>\n<td>Consent. Off unless you opt in; you can withdraw at any time.</td>\n</tr>\n<tr>\n<td>Optional detailed diagnostics: find and fix crashes and slow screens in the app.</td>\n<td>Consent. Off unless you opt in; you can withdraw at any time.</td>\n</tr>\n</tbody></table>\n<p>Where we rely on legitimate interests, those interests include service security, fraud prevention, troubleshooting, product reliability, cost management, and responsible administration. You may object to processing based on legitimate interests (see section 11); we will assess each objection and stop unless we have compelling legitimate grounds, such as security.</p>\n<h2>4. Optional product analytics and detailed diagnostics</h2>\n<p>Both are <strong>off unless you turn them on</strong>, and each is a separate choice. Refusing either one does not change any trip-planning feature or your price.</p>\n<ul>\n<li><strong>Product analytics</strong> records which features you view and use, whether tasks succeed, session timing, your platform and app version, and whether activity happened before, during or after a trip&#39;s scheduled dates. It does not record your location, the text of your trips, messages, prompts, imported content, or anything from Gmail or connected bank accounts. Events are linked to a random pseudonym for your account rather than your name or email; because we can link that pseudonym back to your account, it is still personal data.</li>\n<li><strong>Detailed diagnostics</strong> sends app crash reports and performance timings from your device to Sentry, linked to a random pseudonym. Without this choice, the app sends no crash or performance data from your device; our servers still record their own errors (section 2, necessary technical data).</li>\n</ul>\n<p>You can change either choice at any time under <strong>Account → Privacy</strong> or from the <a href=\"/privacy-choices.html\">Your Privacy Choices</a> page. Withdrawing stops collection immediately. To also erase what was already collected, use <strong>Delete analytics data</strong> in Account → Privacy. If your browser sends a Global Privacy Control or Do Not Track signal, product analytics stays off in that browser. If we materially change what these features collect or why, we will ask you again rather than assume your earlier choice still applies.</p>\n<h2>5. AI-assisted features</h2>\n<p>WanderBunnies may use configured AI providers, which may include OpenAI, Anthropic, Google Gemini, or other providers enabled for a particular feature, to generate itinerary suggestions, parse uploaded travel material, summarize content, or provide chat responses. Depending on the feature, inputs may include destinations, dates, preferences, itinerary text, and relevant uploaded or imported travel content.</p>\n<p>AI output can be inaccurate, incomplete, stale, or unsafe. We do not use AI output as a substitute for professional travel, medical, legal, immigration, or emergency advice. We configure providers and contracts to limit use of submitted data to the disclosed service purposes, but provider-specific retention and location may differ; the current provider configuration must be maintained in our internal subprocessor record. Google user data, including Gmail data and data derived from it, is not used to create, train, or improve a generalized artificial-intelligence or machine-learning model.</p>\n<p>To check and improve AI quality, we may keep a limited record of AI requests and results, identified only by a salted hash rather than your account. These records are deleted automatically within 30 days.</p>\n<p>AI-generated content is labelled where required. You remain responsible for reviewing output before relying on it or sharing it with others.</p>\n<h2>6. Google API and Gmail disclosures</h2>\n<p>When you connect Gmail, we request only the permissions needed for the enabled import feature. We use the authorized Gmail data to identify travel-related messages and attachments, extract itinerary information, show import results, and let you review or delete imported data. We do not use Gmail data for advertising, sell it, or use it for unrelated profiling. We do not read messages after you disconnect, except for data already lawfully retained under the retention rules above.</p>\n<p>Our use and transfer of information received from Google APIs will adhere to the <a href=\"https://developers.google.com/terms/api-services-user-data-policy\">Google API Services User Data Policy</a>, including the Limited Use requirements. We use Google user data only to provide the user-facing features described in this Notice, such as account authentication and the optional Gmail itinerary-import workflow. Google user data is not used for advertising, sold to data brokers, or used to create, train, or improve a generalized artificial-intelligence or machine-learning model. The OAuth consent screen and this Notice must remain consistent with the actual scopes, storage, processing, sharing, and deletion behavior.</p>\n<h2>7. What we do not do</h2>\n<ul>\n<li>We do not sell personal data or share it for cross-context behavioral advertising.</li>\n<li>We do not use advertising identifiers (such as IDFA or the Android advertising ID), device fingerprinting, or session replay.</li>\n<li>We do not collect your precise location or GPS.</li>\n<li>We do not use Gmail, imported email, or connected bank-account content for analytics, advertising, or profiling.</li>\n<li>We do not track you across other companies&#39; apps or websites.</li>\n</ul>\n<h2>8. Sharing and recipients</h2>\n<h3>Sharing you direct</h3>\n<p>WanderBunnies is collaborative. When you join a group, invite someone, follow a shared trip, or post content in a trip, the information you choose to share may be visible to the relevant members and recipients. You are responsible for obtaining appropriate permission before uploading or sharing another person&#39;s information.</p>\n<h3>Service providers</h3>\n<p>We may disclose data to service providers acting under contract, including:</p>\n<ul>\n<li>Firebase and Google Cloud for hosting, authentication, databases, storage, maps, Places, and security services (data stored in the United States);</li>\n<li>Stripe for checkout, subscriptions, tax, billing, fraud prevention, and payment administration;</li>\n<li>configured AI providers for AI-assisted features;</li>\n<li>email and messaging providers such as Mailgun, SMTP, or equivalent providers, and Expo for mobile push notifications;</li>\n<li>Sentry for server error monitoring and, only if you opt in, detailed app diagnostics;</li>\n<li>Unsplash for destination photography;</li>\n<li>SerpAPI for search and discovery data used in attraction and cost-estimate features;</li>\n<li>Plaid, only if you connect a financial account (section 16);</li>\n<li>affiliate partners such as GetYourGuide when you request an eligible referral link; and</li>\n<li>professional advisers, regulators, courts, law enforcement, or a successor entity when legally required or necessary to protect rights and security.</li>\n</ul>\n<p>We do not sell Gmail data or use Google user data for advertising. We do not share personal data with affiliate partners merely because you use the Service; an external partner may receive data when you request or open its link.</p>\n<h2>9. International transfers</h2>\n<p>We and most of our providers process data in the United States. Where data protection law requires it, transfers from the EEA, UK or Switzerland rely on an adequacy decision (including the EU–US Data Privacy Framework for certified providers), the EU Standard Contractual Clauses or UK addendum, or another lawful transfer mechanism, together with appropriate supplementary safeguards. Google Cloud publishes its subprocessor list at <a href=\"https://cloud.google.com/terms/subprocessors\">cloud.google.com/terms/subprocessors</a>. You may request current information about our other service providers and the transfer mechanism used for each by contacting <a href=\"mailto:support@wander-bunnies.com\">support@wander-bunnies.com</a>.</p>\n<h2>10. Retention</h2>\n<p>We keep information only as long as necessary for the purposes above, to provide the Service, resolve disputes, enforce agreements, maintain security, and meet legal, tax, accounting, or regulatory obligations.</p>\n<table>\n<thead>\n<tr>\n<th>Data</th>\n<th>Retention</th>\n</tr>\n</thead>\n<tbody><tr>\n<td>Account and profile data</td>\n<td>While the account is active and until deletion is completed, except for information required for legal, security, fraud-prevention, or dispute purposes.</td>\n</tr>\n<tr>\n<td>Trip and shared content</td>\n<td>Until you or an authorized group member deletes it, the account is deleted, or retention is necessary for a legal or shared-collaboration purpose. Shared content may be retained in de-identified or group-scoped form where needed to preserve another member&#39;s trip.</td>\n</tr>\n<tr>\n<td>Uploads, imported documents, parsed items, and Gmail data</td>\n<td>Until the item is deleted, Gmail is disconnected, the account is deleted, or a shorter feature-specific period ends, subject to legal and security exceptions.</td>\n</tr>\n<tr>\n<td>OAuth tokens</td>\n<td>Until disconnect, expiry, account deletion, or revocation, whichever occurs first.</td>\n</tr>\n<tr>\n<td>Optional product analytics events</td>\n<td>90 days, then deleted. Summaries linked to your account: up to 13 months. Only collected if you opt in.</td>\n</tr>\n<tr>\n<td>Optional detailed diagnostics (Sentry)</td>\n<td>Expire within 30 days. Only collected if you opt in.</td>\n</tr>\n<tr>\n<td>AI quality records</td>\n<td>Deleted within 30 days.</td>\n</tr>\n<tr>\n<td>Service usage and cost metering</td>\n<td>Linked to your account and trip for up to 13 months; after that only totals per feature and provider remain.</td>\n</tr>\n<tr>\n<td>Record of your privacy choices</td>\n<td>While your account exists and for 3 years after it is deleted, kept under a pseudonymous key, so we can show what you agreed to.</td>\n</tr>\n<tr>\n<td>Billing and accounting records</td>\n<td>For the period required by tax, accounting, consumer-protection, and payment laws (generally 7 years).</td>\n</tr>\n<tr>\n<td>Security, diagnostic, and audit logs</td>\n<td>For the shortest period reasonably necessary to investigate incidents, protect the Service, comply with legal duties, and defend claims.</td>\n</tr>\n<tr>\n<td>Backups</td>\n<td>Until overwritten or securely deleted under the documented backup lifecycle.</td>\n</tr>\n</tbody></table>\n<h2>11. Your rights</h2>\n<p>Depending on where you live and subject to legal exceptions, you have the following rights regarding your personal data:</p>\n<ul>\n<li><strong>Access:</strong> Request a copy of the data we hold about you. <strong>Export account data</strong> in Account → Privacy gives you a machine-readable copy, including your privacy choices, analytics-related records and cost metering.</li>\n<li><strong>Rectification:</strong> Request correction of inaccurate or incomplete data.</li>\n<li><strong>Erasure (&quot;Right to be Forgotten&quot;):</strong> Delete your account in Account settings, or delete only your analytics and diagnostics data with <strong>Delete analytics data</strong> in Account → Privacy. You can see the progress of a deletion request in the app.</li>\n<li><strong>Restriction:</strong> Request that we limit how we process your data.</li>\n<li><strong>Data Portability:</strong> Receive your data in a structured, machine-readable format to transfer to another service.</li>\n<li><strong>Object:</strong> Object to processing based on legitimate interests (including cost metering and security logs) or to direct marketing.</li>\n<li><strong>Automated Decision-Making:</strong> Request human intervention if a decision with legal effects was made solely by automated processing. We do not make such decisions.</li>\n<li><strong>Withdraw Consent:</strong> Withdraw any consent at any time, including product analytics and detailed diagnostics.</li>\n</ul>\n<p>Deletion may not remove information that another user lawfully contributed to a shared trip or information we must retain by law; when you delete your account we tell you what is retained and why.</p>\n<p>Submit other requests to <a href=\"mailto:support@wander-bunnies.com\">support@wander-bunnies.com</a>. We respond within one month under the GDPR and UK GDPR (extendable by up to two further months for complex requests, in which case we will tell you), or within 45 days under California and similar US state laws (extendable once by 45 days with notice). You may complain to the data-protection authority in your country of residence, place of work, or the alleged infringement.</p>\n<h2>12. Security</h2>\n<p>We use administrative, technical, and organizational safeguards appropriate to the risks, including access controls, encryption in transit, encryption of sensitive tokens at rest, provider security controls, authentication protections, logging, rate limits, and incident-response procedures. No system is completely secure. If we identify a data breach that legally requires notification, we will notify affected people and authorities as required.</p>\n<h2>13. Children</h2>\n<p>Accounts require age 16 or older everywhere; we confirm this when an account is created or first used. A person under 16 may not create or hold an account, and we do not knowingly collect children&#39;s personal data through account creation.</p>\n<p>An adult account holder may enter travel information for a minor dependent or family member as part of planning a shared trip, such as adding them as a traveler or including their travel documents. The adult submitting that information is responsible for having the authority to provide it and for its accuracy. Minors and other travelers without an account are never subjects of product analytics or diagnostics. If you believe a child has created an account or otherwise provided personal data directly and improperly, contact us so we can investigate and delete it where appropriate.</p>\n<h2>14. US state privacy rights</h2>\n<p>Residents of California and other US states may have rights to know or access, correct, delete, obtain a portable copy, limit the use of sensitive personal data, opt out of sale, sharing or targeted advertising, appeal a decision about a request, and receive equal service. These rights apply subject to the thresholds, definitions, and exemptions in the relevant law. We do not sell or share personal data for cross-context behavioral advertising. We honor Global Privacy Control as an opt-out signal. To appeal a decision about your request, reply to our response or email <a href=\"mailto:support@wander-bunnies.com\">support@wander-bunnies.com</a> with &quot;Appeal&quot; in the subject. See <a href=\"/privacy-choices.html\">Your Privacy Choices</a>.</p>\n<h2>15. Changes</h2>\n<p>We may update this Notice to reflect changes to the Service, providers, law, or processing. Each version has a number, an effective date and a summary of what changed. For a material change to optional analytics or diagnostics, we will ask for your choice again rather than assume your earlier choice still applies.</p>\n<h2>16. Financial account connections (optional)</h2>\n<p><strong>This feature is off by default and only available if you turn it on.</strong> If you choose to connect a bank or credit card account to import transactions as trip expenses:</p>\n<ul>\n<li><strong>What we collect.</strong> Through our service provider Plaid, we receive transaction-level data from your connected account: dates, amounts, merchant names, and Plaid&#39;s own category labels. We may also receive the connected institution and account identifiers needed to keep one connection&#39;s updates separate from another. We do not receive, and never ask you for, your bank username, password, or multi-factor authentication codes — those are entered only within Plaid&#39;s own secure connection flow, which we do not have access to.</li>\n<li><strong>Why we collect it.</strong> Solely so you can review recent transactions and, if you choose, import individual ones as expenses on a specific trip. We do not use this data for credit scoring, marketing, advertising, or any purpose other than the expense-import feature you activated. We do not sell this data or share it for advertising or profiling. Plaid and Firebase/Google Cloud process it as service providers required to operate this feature.</li>\n<li><strong>What we don&#39;t automatically do.</strong> Connecting an account does not automatically create expenses. Every transaction requires your explicit confirmation before it becomes part of a trip&#39;s records.</li>\n<li><strong>Retention and deletion.</strong> Imported transaction data you have not confirmed into an expense is retained only while your account connection stays active. If you disconnect an account, or if Plaid sends us a permission/account-revocation webhook, we stop syncing and delete that connection and the affected unconfirmed transaction data automatically. Transactions you&#39;ve already confirmed into a trip expense are retained like any other expense you entered manually, and are covered by this policy&#39;s general retention/deletion terms — not deleted just because the underlying connection is later removed. Account deletion also queues deletion of the Plaid connection and its remaining derived data.</li>\n<li><strong>Your control.</strong> You can disconnect a linked account at any time from Account Settings. Doing so immediately revokes our access at Plaid and triggers the deletion described above.</li>\n<li><strong>Security.</strong> Your account access token is encrypted before storage and is never exposed to the app&#39;s client, to other users, or to anyone but the automated systems that need it to sync transactions on your behalf.</li>\n<li><strong>No sale or advertising.</strong> We do not use connected-account data for credit decisions, advertising, marketing profiles, or data-broker activity.</li>\n</ul>\n<h2>17. Related documents</h2>\n<p><a href=\"/terms.html\">Consumer Terms</a> · <a href=\"/privacy-choices.html\">Your Privacy Choices</a> · <a href=\"/cookies.html\">Cookie Notice</a> · <a href=\"/delete-account.html\">Delete your account</a> · <a href=\"/withdrawal.html\">Withdrawal Form</a> · <a href=\"/content-moderation.html\">Content Moderation and DSA Procedure</a></p>\n<div class=\"footer\">&copy; 2026 WanderBunnies · Owned and operated by Tristan Duerk · Version 3.0, effective October 8, 2026</div>\n</body>\n</html>\n";
